CREATE TABLE customers(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), name TEXT NOT NULL, phone TEXT NOT NULL, email TEXT, suppressed INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, UNIQUE(tenant_id,id), UNIQUE(tenant_id,phone));
CREATE TABLE bookings(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, customer_id TEXT NOT NULL, service_id TEXT NOT NULL, resource_id TEXT NOT NULL, starts_at INTEGER NOT NULL, ends_at INTEGER NOT NULL CHECK(ends_at>starts_at), occupied_until INTEGER NOT NULL CHECK(occupied_until>=ends_at), price_centimes INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'confirmed' CHECK(status IN ('confirmed','cancelled','completed','no_show')), source TEXT NOT NULL, manage_hash TEXT NOT NULL, manage_expires INTEGER NOT NULL, revision INTEGER NOT NULL DEFAULT 1, config_revision INTEGER NOT NULL, idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, response_cipher TEXT NOT NULL, consent_email INTEGER NOT NULL, consent_whatsapp INTEGER NOT NULL, consent_marketing INTEGER NOT NULL, consent_at INTEGER NOT NULL, created_at INTEGER NOT NULL, UNIQUE(tenant_id,id), UNIQUE(tenant_id,idempotency_key), FOREIGN KEY(tenant_id) REFERENCES tenants(id), FOREIGN KEY(tenant_id,customer_id) REFERENCES customers(tenant_id,id), FOREIGN KEY(tenant_id,service_id) REFERENCES services(tenant_id,id), FOREIGN KEY(tenant_id,resource_id) REFERENCES resources(tenant_id,id));
CREATE TRIGGER booking_config_insert BEFORE INSERT ON bookings BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM tenants WHERE id=NEW.tenant_id AND revision=NEW.config_revision AND active=1 AND (paused=0 OR NEW.source IN ('manual','whatsapp','walk_in'))) THEN RAISE(ABORT,'stale_configuration') END; END;
CREATE TRIGGER booking_config_update BEFORE UPDATE OF starts_at,resource_id ON bookings BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM tenants WHERE id=NEW.tenant_id AND revision=NEW.config_revision AND active=1) THEN RAISE(ABORT,'stale_configuration') END; END;
CREATE TABLE booking_claims(tenant_id TEXT NOT NULL, resource_id TEXT NOT NULL, slot_utc INTEGER NOT NULL CHECK(slot_utc%300000=0), booking_id TEXT NOT NULL, PRIMARY KEY(tenant_id,resource_id,slot_utc), FOREIGN KEY(tenant_id,booking_id) REFERENCES bookings(tenant_id,id), FOREIGN KEY(tenant_id,resource_id) REFERENCES resources(tenant_id,id));
CREATE INDEX claims_booking ON booking_claims(tenant_id,booking_id);
CREATE INDEX bookings_calendar ON bookings(tenant_id,starts_at,status);
CREATE INDEX bookings_customer ON bookings(tenant_id,customer_id,status);
CREATE TABLE booking_operations(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, booking_id TEXT NOT NULL, expected_revision INTEGER NOT NULL, kind TEXT NOT NULL, created_at INTEGER NOT NULL, FOREIGN KEY(tenant_id,booking_id) REFERENCES bookings(tenant_id,id));
CREATE TRIGGER booking_operation_guard BEFORE INSERT ON booking_operations BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM bookings WHERE tenant_id=NEW.tenant_id AND id=NEW.booking_id AND revision=NEW.expected_revision AND status='confirmed') THEN RAISE(ABORT,'stale_booking') END; END;
CREATE TABLE notification_outbox(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), booking_id TEXT, customer_id TEXT, kind TEXT NOT NULL, channel TEXT NOT NULL CHECK(channel IN ('email','whatsapp')), event_key TEXT NOT NULL, payload_cipher TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','leased','provider_accepted','delivered','failed_retryable','failed_final','suppressed','uncertain')), due_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, lease_until INTEGER, lease_token TEXT, provider_id TEXT, reason TEXT, accepted_at INTEGER, delivered_at INTEGER, created_at INTEGER NOT NULL, UNIQUE(tenant_id,event_key), UNIQUE(channel,provider_id), FOREIGN KEY(tenant_id,booking_id) REFERENCES bookings(tenant_id,id), FOREIGN KEY(tenant_id,customer_id) REFERENCES customers(tenant_id,id));
CREATE INDEX outbox_due ON notification_outbox(state,due_at);
